CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('owner','manager','accountant','caretaker')), active boolean NOT NULL DEFAULT true, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS properties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, address text NOT NULL, city text NOT NULL, contact text NOT NULL DEFAULT '', type text NOT NULL DEFAULT 'Co-living', amenities text NOT NULL DEFAULT '', rules text NOT NULL DEFAULT '', due_day int NOT NULL DEFAULT 5 CHECK(due_day BETWEEN 1 AND 28), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS user_properties (user_id uuid REFERENCES users ON DELETE CASCADE, property_id uuid REFERENCES properties ON DELETE CASCADE, PRIMARY KEY(user_id,property_id));
CREATE TABLE IF NOT EXISTS rooms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties, name text NOT NULL, floor text NOT NULL DEFAULT 'Ground', rent bigint NOT NULL CHECK(rent>=0), UNIQUE(property_id,name));
CREATE TABLE IF NOT EXISTS beds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_id uuid NOT NULL REFERENCES rooms, label text NOT NULL, maintenance boolean NOT NULL DEFAULT false, UNIQUE(room_id,label));
CREATE TABLE IF NOT EXISTS tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, phone text NOT NULL, email text NOT NULL DEFAULT '', emergency_name text NOT NULL DEFAULT '', emergency_phone text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', occupation text NOT NULL DEFAULT '', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS stays (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, property_id uuid NOT NULL REFERENCES properties, bed_id uuid NOT NULL REFERENCES beds, joined_on date NOT NULL, ended_on date, notice_on date, rent bigint NOT NULL CHECK(rent>=0), deposit_expected bigint NOT NULL DEFAULT 0 CHECK(deposit_expected>=0), deposit_paid bigint NOT NULL DEFAULT 0 CHECK(deposit_paid>=0 AND deposit_paid<=deposit_expected), deposit_deduction bigint NOT NULL DEFAULT 0 CHECK(deposit_deduction>=0), deposit_refund bigint NOT NULL DEFAULT 0 CHECK(deposit_refund>=0), settlement_reason text NOT NULL DEFAULT '', agreement_expires date, CHECK(ended_on IS NULL OR ended_on>=joined_on));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_bed ON stays(bed_id) WHERE ended_on IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS one_active_tenant ON stays(tenant_id) WHERE ended_on IS NULL;
CREATE TABLE IF NOT EXISTS invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), number bigint GENERATED ALWAYS AS IDENTITY UNIQUE, property_id uuid NOT NULL REFERENCES properties, stay_id uuid NOT NULL REFERENCES stays, period text NOT NULL, description text NOT NULL, kind text NOT NULL DEFAULT 'rent' CHECK(kind IN ('rent','charge')), amount bigint NOT NULL CHECK(amount>0), due_on date NOT NULL, created_at timestamptz DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS unique_monthly_rent ON invoices(stay_id,period) WHERE kind='rent';
CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES invoices, amount bigint NOT NULL CHECK(amount>0), method text NOT NULL CHECK(method IN ('UPI','Cash','Bank transfer')), reference text NOT NULL DEFAULT '', paid_on date NOT NULL, created_by uuid NOT NULL REFERENCES users, idempotency_key uuid UNIQUE NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS expenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties, category text NOT NULL, description text NOT NULL, amount bigint NOT NULL CHECK(amount>0), spent_on date NOT NULL, status text NOT NULL CHECK(status IN ('Paid','Pending')), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS complaints (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties, title text NOT NULL, location text NOT NULL, priority text NOT NULL CHECK(priority IN ('Low','Medium','High')), status text NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','In progress','Resolved')), assigned_to text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties, name text NOT NULL, phone text NOT NULL, move_in date NOT NULL, follow_up date, notes text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'New' CHECK(status IN ('New','Contacted','Converted','Cancelled')), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties, tenant_id uuid REFERENCES tenants, name text NOT NULL, category text NOT NULL, file_key text UNIQUE NOT NULL, mime text NOT NULL, size int NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users, property_id uuid REFERENCES properties, action text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS login_attempts (key text PRIMARY KEY, attempts int NOT NULL DEFAULT 1, started_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS stays_property ON stays(property_id);
CREATE INDEX IF NOT EXISTS invoices_property ON invoices(property_id);
CREATE INDEX IF NOT EXISTS payments_invoice ON payments(invoice_id);
CREATE INDEX IF NOT EXISTS audit_created ON audit_logs(created_at DESC);

ALTER TABLE users ADD COLUMN IF NOT EXISTS session_version integer NOT NULL DEFAULT 0;
